import { mkdirSync } from "node:fs";
import { resolve } from "node:path";
import Database from "better-sqlite3";
import { betterAuth } from "better-auth";
import { admin, username } from "better-auth/plugins";
import { roles } from "./roles.js";

const dataDir = resolve(process.cwd(), process.env.DATA_DIR ?? "./data");
mkdirSync(dataDir, { recursive: true });

export const auth = betterAuth({
  appName: "nlhack",
  secret: process.env.BETTER_AUTH_SECRET,
  baseURL: process.env.BETTER_AUTH_URL ?? "http://localhost:3000",
  database: new Database(resolve(dataDir, "auth.db")),
  // Users are created only by the seed script via the admin API.
  emailAndPassword: { enabled: true, disableSignUp: true },
  plugins: [
    username(),
    admin({ roles, defaultRole: "employee", adminRoles: ["admin"] }),
  ],
});

export type Session = typeof auth.$Infer.Session;
export type Role = "admin" | "employee";
import { adminAc, userAc } from "better-auth/plugins/admin/access";

// Custom role names must be registered in `roles`, otherwise setRole/createUser reject them.
// employee mirrors the built-in "user" role (no admin permissions); admin is the built-in admin role.
export const roles = { employee: userAc, admin: adminAc };
import { getMigrations } from "better-auth/db/migration";
import { auth } from "./index.js";

const { toBeCreated, toBeAdded, runMigrations } = await getMigrations(auth.options);

if (toBeCreated.length === 0 && toBeAdded.length === 0) {
  console.info("Auth schema is up to date.");
} else {
  await runMigrations();
  for (const t of toBeCreated) console.info(`Created table ${t.table}: ${Object.keys(t.fields).join(", ")}`);
  for (const t of toBeAdded) console.info(`Added to ${t.table}: ${Object.keys(t.fields).join(", ")}`);
}
